<?php
declare(strict_types=1);$pageTitle='Narrative Manager';$topNavSection='roleplay';$BODY_CLASS='hub-page';require __DIR__.'/ui_bootstrap.php';$rows=$uiRepository->rows('narratives');$installations=$uiRepository->rows('installations');$profiles=array_merge($uiRepository->rows('characters'),$uiRepository->rows('player'),$uiRepository->rows('narrator'));$playthroughs=$uiRepository->rows('playthroughs');
$installationLabels=[];foreach($installations as$row)$installationLabels[(string)$row['installation_id']]=(string)$row['display_name'];
/** Group a scope select by installation so a manual diary request cannot silently mix installations. */
$diaryScopeSelect=static function(string $id,string $name,array $rows,string $idField,string $labelField,bool $groupByInstallation=true)use($installationLabels):void{
    $grouped=[];foreach($rows as$row)$grouped[$groupByInstallation?($installationLabels[(string)($row['installation_id']??'')]??'Unknown installation'):''][]=$row;
    ksort($grouped);$useGroups=$groupByInstallation&&count($grouped)>1;
    echo'<select id="'.almsivi_ui_h($id).'" name="'.almsivi_ui_h($name).'" required>';
    foreach($grouped as$group=>$groupRows){if($useGroups)echo'<optgroup label="'.almsivi_ui_h((string)$group).'">';
        foreach($groupRows as$row)echo'<option value="'.almsivi_ui_h((string)$row[$idField]).'">'.almsivi_ui_h((string)($row[$labelField]??'')).'</option>';
        if($useGroups)echo'</optgroup>';}
    echo'</select>';};
$diaryScopeReady=$installations!==[]&&$profiles!==[]&&$playthroughs!==[];
include __DIR__.'/tmpl/head.html';if(!$embedded)include __DIR__.'/tmpl/navbar.php';?>
<main class="almsivi-page<?php echo $embedded?' embedded':''; ?>"><header class="almsivi-page-header"><div><h1>Narratives</h1><p>Create scoped narrator, diary, and summary records included in roleplay context.</p></div><span class="almsivi-badge"><?php echo count($rows); ?> narratives</span></header><?php $status=(string)($_GET['status']??''); ?><?php if($status==='diary-requested'): ?><div class="almsivi-status" role="status">Diary generation queued. One diary narrative is written in the background; check Workers &amp; Jobs for progress, then reload this page to read it.</div><?php elseif($status!==''): ?><div class="almsivi-status" role="status">Narrative saved.</div><?php endif; ?><section class="almsivi-card" aria-labelledby="diary-generate-heading"><h2 id="diary-generate-heading">Request a diary</h2><p class="almsivi-muted" id="diary-generate-help">Queues one diary narrative written from the bounded witnessed context the selected profile already has in the selected playthrough. It runs once, in the background, only when you submit this form. ALMSIVI never generates a diary on a timer, during sleep or wait, or as a physical in-game book.</p><?php if(!$diaryScopeReady): ?><p class="almsivi-muted">A diary request needs at least one installation, one profile, and one playthrough. Connect OpenMW and start a playthrough first.</p><?php else: ?><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/narrative-generate"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><div class="almsivi-form-grid"><label for="diary-generate-installation">Installation<?php $diaryScopeSelect('diary-generate-installation','installation_id',$installations,'installation_id','display_name',false); ?></label><label for="diary-generate-profile">Profile<?php $diaryScopeSelect('diary-generate-profile','profile_id',$profiles,'profile_id','name'); ?></label><label for="diary-generate-playthrough">Playthrough<?php $diaryScopeSelect('diary-generate-playthrough','playthrough_id',$playthroughs,'playthrough_id','playthrough'); ?></label></div><p class="almsivi-muted" id="diary-generate-requirements">The profile must opt in first: turn <strong>Manual Diary Generation</strong> on and choose a <strong>Diary LLM</strong> in <a href="<?php echo almsivi_ui_h($webRoot); ?>/ui/core/core_profiles.php">Core Profiles</a>. Without both, the request is refused and nothing is queued. Installation, profile, and playthrough must belong together. A queued job keeps the profile and connector revisions that were current when you submitted it.</p><div class="almsivi-actions"><button type="submit" aria-describedby="diary-generate-help diary-generate-requirements">Queue Diary Generation</button></div></form><?php endif; ?></section><section class="almsivi-card"><h2>Create narrative</h2><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/narratives"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><div class="almsivi-form-grid"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo almsivi_ui_h($row['installation_id']); ?>"><?php echo almsivi_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Profile<select name="profile_id"><?php foreach($profiles as$row): ?><option value="<?php echo almsivi_ui_h($row['profile_id']); ?>"><?php echo almsivi_ui_h($row['name']); ?></option><?php endforeach; ?></select></label><label>Playthrough<select name="playthrough_id"><?php foreach($playthroughs as$row): ?><option value="<?php echo almsivi_ui_h($row['playthrough_id']); ?>"><?php echo almsivi_ui_h($row['playthrough']); ?></option><?php endforeach; ?></select></label><label>Kind<select name="kind"><option value="narrator">Narrator</option><option value="diary">Diary</option><option value="summary">Summary</option></select></label><label>Title<input name="title" required></label><label class="wide">Narrative<textarea name="content" required></textarea></label><label>Provenance<input name="provenance" value="management" required></label></div><div class="almsivi-actions"><button type="submit">Create Narrative</button></div></form></section><section class="almsivi-grid"><?php foreach($rows as$row): ?><article class="almsivi-card"><h2><?php echo almsivi_ui_h($row['title']); ?></h2><p><?php echo nl2br(almsivi_ui_h($row['content'])); ?></p><details><summary>Edit narrative</summary><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/narrative-revise"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="narrative_id" value="<?php echo almsivi_ui_h($row['narrative_id']); ?>"><label>Kind<select name="kind"><?php foreach(['narrator','diary','summary']as$kind): ?><option<?php echo $row['kind']===$kind?' selected':''; ?>><?php echo almsivi_ui_h($kind); ?></option><?php endforeach; ?></select></label><label>Title<input name="title" required value="<?php echo almsivi_ui_h($row['title']); ?>"></label><label>Narrative<textarea name="content" required><?php echo almsivi_ui_h($row['content']); ?></textarea></label><label>Provenance<input name="provenance" value="management edit" required></label><div class="almsivi-actions"><button type="submit">Save Narrative</button></div></form></details><form method="post" action="<?php echo almsivi_ui_h($managementBasePath); ?>/forms/narrative-delete" data-confirm="Delete this narrative?"><input type="hidden" name="_csrf" value="<?php echo almsivi_ui_h($csrf); ?>"><input type="hidden" name="narrative_id" value="<?php echo almsivi_ui_h($row['narrative_id']); ?>"><button class="danger" type="submit">Delete</button></form></article><?php endforeach; ?><?php if($rows===[]): ?><article class="almsivi-card almsivi-empty">No narratives exist yet.</article><?php endif; ?></section></main><?php include __DIR__.'/tmpl/footer.html'; ?>
